INSERT INTO listening_contents (lesson_id, title, audio_url, transcript, description, sort_order) SELECT ls.id, 'Bài 50 - Track C-35: 総合問題 (CD C-35)', '/audio/n4/lesson-50/listening-04.mp3', 'Kịch bản nghe Bài 50 Track C-35', 'Bài tập 4: 総合敬語問題・面接会話 (Track C-35)', 4 FROM lessons ls JOIN levels lv ON ls.level_id = lv.id WHERE lv.code = 'N4' AND ls.lesson_number = 50 AND NOT EXISTS (SELECT 1 FROM listening_contents WHERE audio_url = '/audio/n4/lesson-50/listening-04.mp3');
